INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('이즈모 가미아리사이', '出雲大社 神在祭', '島根県', '出雲市', DATE '2026-11-18', DATE '2026-11-25', 2026, 35.402000, 132.685500, '음력 10월 전국 신들이 이즈모에 모여 사람들의 인연을 정한다는 신화를 잇는 제례. 첫날 밤 이나사 해변에서 신을 맞는 가미무카에 신사가 열린다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('이쓰쿠시마 간겐사이', '厳島神社 管絃祭', '広島県', '廿日市市', DATE '2027-07-20', DATE '2027-07-20', 2027, 34.295900, 132.319900, '헤이안 귀족의 뱃놀이를 신사로 옮긴 미야지마 최대 제례. 밤바다 위에서 아악을 연주하는 배가 등불을 밝히고 바다 위 도리이 앞을 지난다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나라 도카에', 'なら燈花会', '奈良県', '奈良市', DATE '2027-08-05', DATE '2027-08-14', 2027, 34.685000, 135.840000, '나라 공원 일대에 2만 개가 넘는 촛불을 놓아 고도의 밤을 밝히는 여름 행사. 사루사와 연못, 우키미도 등 명소마다 촛불이 물에 비친다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('요사코이 마쓰리', 'よさこい祭り', '高知県', '高知市', DATE '2027-08-09', DATE '2027-08-12', 2027, 33.559000, 133.531000, '나루코를 들고 자유로운 안무로 춤추는 ''요사코이'' 춤의 발상지 축제. 약 200개 팀이 화려한 의상과 지방차(음향 트럭)를 앞세워 시내를 행진한다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('아와오도리', '阿波おどり', '徳島県', '徳島市', DATE '2027-08-12', DATE '2027-08-15', 2027, 34.070000, 134.554000, '''추는 바보에 보는 바보, 같은 바보면 추는 게 이득''이라는 구호로 유명한 400년 역사의 봉오도리. 나흘간 시내 곳곳 무대와 거리에서 ''렌''이라 부르는 무용단이 춤춘다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('고잔노오쿠리비', '京都五山送り火', '京都府', '京都市', DATE '2027-08-16', DATE '2027-08-16', 2027, 35.023000, 135.800000, '오봉에 돌아온 조상의 영혼을 배웅하는 교토의 여름 행사. 20시부터 히가시야마의 ''大''를 시작으로 다섯 산에 차례로 불 글자가 켜진다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('사이조 마쓰리', '西条まつり', '愛媛県', '西条市', DATE '2027-10-14', DATE '2027-10-17', 2027, 33.894000, 133.208000, '가마를 닮은 수레(단지리) 150여 대가 등불을 켜고 밤새 시내를 도는 에히메의 가을 축제. 16일 가모강에 수레가 들어가는 ''가와이리''가 절정이다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('니이하마 다이코 마쓰리', '新居浜太鼓祭り', '愛媛県', '新居浜市', DATE '2027-10-16', DATE '2027-10-18', 2027, 33.960000, 133.283000, '무게 약 3톤의 화려한 북 수레(다이코다이) 50여 대를 150명이 메고 겨루는 시코쿠 3대 축제. 수레끼리 부딪치는 ''하치아와세''가 볼거리다.', NULL, NULL, DATE '2026-11-14', NULL);